#include <bits/stdc++.h>
using namespace std;


inline int in() { int x; scanf("%d", &x); return x; }
const int N = 5005;

int comp[N], bfsDist[N], bfsPar[N];
vector <int> g[N], gR[N];
bool mark[N], inCycle[N];

bool dfs(int v, vector <int> *g, vector <int> &nodes)
{
	mark[v] = 1;
	for(int u : g[v])
		if(!mark[u])
			dfs(u, g, nodes);
	nodes.push_back(v);
}

int findSmallestCycle(vector <int> vs)
{
	vector <int> cycle;
	for(int root : vs)
	{
		for(int v : vs)
		{
			bfsDist[v] = 1e9;
			bfsPar[v] = -1;
		}
		bfsDist[root] = 0;
		queue <int> q;
		q.push(root);
		bool cycleFound = 0;
		while(q.size() && !cycleFound)
		{
			int v = q.front();
			q.pop();
			for(int u : g[v])
			{
				if(u == root)
				{
					cycleFound = 1;
					int curLen = bfsDist[v];
					if(cycle.empty() || curLen < cycle.size())
					{
						cycle.clear();
						for(; v != -1; v = bfsPar[v])
							cycle.push_back(v);
					}
					break;
				}
				if(bfsDist[u] > bfsDist[v] + 1)
				{
					bfsDist[u] = bfsDist[v] + 1;
					bfsPar[u] = v;
					q.push(u);
				}
			}
		}
	}
	return cycle.size();
}

int main()
{
	int n, m;
	cin >> n >> m;
	for(int i = 0; i < m; i++)
	{
		int u = in() - 1;
		int v = in() - 1;
		g[u].push_back(v);
		gR[v].push_back(u);
	}
	vector <int> order;
	for(int i = 0; i < n; i++)
		if(!mark[i])
			dfs(i, g, order);

	fill(mark, mark + n, 0);
	fill(comp, comp + n, -1);
	int inCycle = 0, nCycle = 0;
	for(; order.size(); order.pop_back())
	{
		int v = order.back();
		if(mark[v])
			continue;
		vector <int> curComp;
		dfs(v, gR, curComp);
		bool isSink = true;
		for(int u : curComp)
			comp[u] = v;
		for(int u : curComp)
			for(int k = 0; k < g[u].size(); k++)
				if(comp[g[u][k]] != v)
					isSink = false;
		if(isSink)
		{
			int x = findSmallestCycle(curComp);
			if(x > 0)
			{
			    nCycle++;
			    inCycle += x;
			}
		}
	}
	cout << 999 * inCycle + (n - inCycle) + nCycle << endl;

}
